(async () => {
  const root = document.querySelector('[data-window-gallery]');
  root.scrollIntoView();
  await new Promise(r => setTimeout(r, 6000));
  const g = window.__wgDebug;
  const boxes = [];
  g.scene.traverse(o => {
    if (!o.isMesh) return;
    o.geometry.computeBoundingBox();
    const b = o.geometry.boundingBox.clone().applyMatrix4(o.matrixWorld);
    boxes.push({name: o.name || o.type, min: b.min.toArray().map(n=>+n.toFixed(1)), max: b.max.toArray().map(n=>+n.toFixed(1))});
  });
  // straight-on camera
  g.camera.position.set(0, 0, 14);
  g.camera.lookAt(0, 0, 0);
  g.camera.updateMatrixWorld();
  g.renderer.render(g.scene, g.camera);
  const url = g.renderer.domElement.toDataURL('image/png');
  return {boxes: boxes.slice(0, 8), count: boxes.length, img: url};
})()
